"use client";

import { useScroll, useTransform, motion } from "framer-motion";
import { useRef } from "react";

interface Image {
    src: string;
    alt?: string;
    title?: string;
    subtitle?: string;
}

interface ZoomParallaxProps {
    /** Array of images to be displayed in the parallax effect max 7 images */
    images: Image[];
}

export function ZoomParallax({ images }: ZoomParallaxProps) {
    const container = useRef(null);
    const { scrollYProgress } = useScroll({
        target: container,
        offset: ["start start", "end end"],
    });

    const scale4 = useTransform(scrollYProgress, [0, 1], [1, 4]);
    const scale5 = useTransform(scrollYProgress, [0, 1], [1, 5]);
    const scale6 = useTransform(scrollYProgress, [0, 1], [1, 6]);
    const scale8 = useTransform(scrollYProgress, [0, 1], [1, 8]);
    const scale9 = useTransform(scrollYProgress, [0, 1], [1, 9]);

    const contentScale = useTransform(scrollYProgress, [0, 1], [1, 0.15]);

    const scales = [scale4, scale5, scale6, scale5, scale6, scale8, scale9];

    return (
        <div ref={container} className="relative h-[300vh]">
            <div className="sticky top-0 h-screen overflow-hidden bg-background">
                {images.map(({ src, alt, title, subtitle }, index) => {
                    const scale = scales[index % scales.length];

                    return (
                        <motion.div
                            key={index}
                            style={{ scale }}
                            className={`absolute top-0 flex h-full w-full items-center justify-center ${index === 1
                                ? "[&>div]:!-top-[30vh] [&>div]:!left-[5vw] [&>div]:!h-[30vh] [&>div]:!w-[35vw]"
                                : ""
                                } ${index === 2
                                    ? "[&>div]:!-top-[10vh] [&>div]:!-left-[25vw] [&>div]:!h-[45vh] [&>div]:!w-[20vw]"
                                    : ""
                                } ${index === 3
                                    ? "[&>div]:!left-[27.5vw] [&>div]:!h-[25vh] [&>div]:!w-[25vw]"
                                    : ""
                                } ${index === 4
                                    ? "[&>div]:!top-[27.5vh] [&>div]:!left-[5vw] [&>div]:!h-[25vh] [&>div]:!w-[20vw]"
                                    : ""
                                } ${index === 5
                                    ? "[&>div]:!top-[27.5vh] [&>div]:!-left-[22.5vw] [&>div]:!h-[25vh] [&>div]:!w-[30vw]"
                                    : ""
                                } ${index === 6
                                    ? "[&>div]:!top-[22.5vh] [&>div]:!left-[25vw] [&>div]:!h-[15vh] [&>div]:!w-[15vw]"
                                    : ""
                                } `}
                        >
                            <div className="relative h-[25vh] w-[25vw] overflow-hidden rounded-2xl shadow-2xl">
                                <img
                                    src={src || "/placeholder.svg"}
                                    alt={alt || `Parallax image ${index + 1}`}
                                    className="h-full w-full object-cover"
                                />
                                {(title || subtitle) && (
                                    <motion.div
                                        style={{ scale: contentScale }}
                                        className="absolute inset-0 flex flex-col items-center justify-center text-white p-4 text-center transition-colors"
                                    >
                                        {title && (
                                            <div className="relative mb-4">
                                                <h3
                                                    className="relative text-3xl md:text-5xl font-medium tracking-tight text-white drop-shadow-md"
                                                    style={{ fontFamily: '"Helvetica Neue", Helvetica, Arial, sans-serif' }}
                                                >
                                                    {/* Depth shadow layers */}
                                                    <span
                                                        className="absolute inset-0 text-white/30 blur-[1px]"
                                                        style={{ transform: "translate(2px, 2px)" }}
                                                        aria-hidden="true"
                                                    >
                                                        {title}
                                                    </span>
                                                    <span
                                                        className="absolute inset-0 text-white/20 blur-[0.5px]"
                                                        style={{ transform: "translate(1px, 1px)" }}
                                                        aria-hidden="true"
                                                    >
                                                        {title}
                                                    </span>
                                                    {/* Main text */}
                                                    <span className="relative">{title}</span>
                                                </h3>
                                            </div>
                                        )}
                                        {subtitle && (
                                            <p className="mt-2 text-lg md:text-xl font-medium text-white/90 drop-shadow-sm max-w-md">
                                                {subtitle}
                                            </p>
                                        )}
                                        <button className="mt-6 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-white/90 transition-colors shadow-lg">
                                            Book Appointment
                                        </button>
                                    </motion.div>
                                )}
                            </div>
                        </motion.div>
                    );
                })}
            </div>
        </div>
    );
}
